# THE ROWS built from the spec's lines: (name, op, subject, en, he with its gloss, ink, corpus, exam)
CELLN = {k: v for k, v in S.CELLS.items()}
SUBJ_EN = {'israel_people': 'Israel', 'reuben': 'Reuben', 'judah': 'Judah', 'levi': 'Levi', 'benjamin': 'Benjamin', 'joseph': 'Joseph', 'zebulun': 'Zebulun', 'issachar': 'Issachar', 'gad': 'Gad', 'dan_son': 'Dan (the entity dan_son)', 'naphtali': 'Naphtali', 'asher': 'Asher'}
# the he's seat is the verse PHRASE found it in — read from the phrase table's own call above (the verse typed beside the tokens), never a second typing
HV = {}
for l in open(__file__, encoding='utf-8').read().split('\n'):
    for m in re.finditer(r"H\['([a-z_]+)'\] = PHRASE\(D, (33), (\d+), ", l): HV[m.group(1)] = (m.group(2), m.group(3))
assert len(HV) == 28 and set(HV) == set(OWN28), (len(HV), set(OWN28) - set(HV))
NEW = []
for kind, first, rng, claim, cell, form, fields, effs, reuses in S.LINES:
    c_, lo_, hi_ = RNG(rng)
    for name, op, sub in effs:
        en, gloss, ink, ask = E[name]
        assert ask in fields, (name, ask, fields)
        assert int(HV[name][0]) == c_ and lo_ <= int(HV[name][1]) <= hi_, (name, HV[name], rng)   # the phrase's verse inside its line's range
        assert ('on ' + SUBJ_EN[sub].split(' (')[0]) in en, (name, sub, en[:120])   # the subject named in the value
        NEW.append((name, op, sub, en, "%s (%s — Deut %s:%s)" % (H[name], gloss, HV[name][0], HV[name][1]), ink, CORPUS, EX % (cell, CELLN[cell], ask, kind)))
assert len(NEW) == 28 and [n for n, *_ in NEW] == list(OWN28), (len(NEW), [n for n, *_ in NEW][:3])
assert all(H[n] in he for n, op, sub, en, he, *_ in NEW), 'every he from the phrase table'
added = 0
for name, op, sub, en, he, ink, corpus, exam in NEW:
    if name in fx: continue
    text = text.rstrip('\n') + '\n' + f"  {name}:\n    en: {q(en)}\n    he: {q(he)}\n    ledger_op: {op}   # {W21}: chapter 33's compile, LEAN — {name} on {sub}, the name and the value from the spine's rows, Onkelos, the outside rows and the fifteen Mishnah and Tosefta rows\n    ink: {q(ink)}\n    corpus: {q(corpus)}\n    exam: {q(exam)}\n"
    added += 1
# ---- NO REUSED ROW (the spec's REUSES empty — no effect's own forward seat lies in the chapter; 20b amended three) ----
assert S.REUSES == [] and S.REUSE_BEFORE == {} and S.REUSE_AFTER == {}
if not CHECK:
    open(path, 'w', encoding='utf-8').write(text)
fx = yaml.safe_load(open(path, encoding='utf-8'))['effects']
assert CHECK or (all(n in fx for n, *_ in NEW) and all(fx[n]['ledger_op'] == 'status' for n, *_ in NEW))
C = S.counts()
assert sum(1 for n, op, *_ in NEW if op == 'block') == 0 == C['ops'].get('block', 0) and sum(1 for n, op, *_ in NEW if op == 'status') == 28 == C['ops']['status'] and sum(1 for n, op, *_ in NEW if op == 'heaven') == 0 == C['ops'].get('heaven', 0), (sum(1 for n, op, *_ in NEW if op == 'status'), sum(1 for n, op, *_ in NEW if op == 'heaven'))
SUBC = {}
for n, op, sub, *_ in NEW: SUBC[sub] = SUBC.get(sub, 0) + 1
assert SUBC == {'israel_people': 10, 'reuben': 1, 'judah': 1, 'levi': 4, 'benjamin': 1, 'joseph': 3, 'zebulun': 1, 'issachar': 1, 'gad': 2, 'dan_son': 1, 'naphtali': 1, 'asher': 2} == C['subjects_new'], (SUBC, C['subjects_new'])
print('the kin rows\' ops as the registry holds them:', ' '.join('%s=%s' % (k, v) for k, v in sorted(KIN_OPS.items())))
print('effects: %d %s (registry %d) — 28 status / 0 block / 0 heaven on %s; no reused row; the he found in the verses: %s' % (added, 'to add' if CHECK else 'added', len(fx), SUBC, ' | '.join('%s=%s' % (k, v) for k, v in H.items())))
